-- DealerOps demo seed: 30 dealerships, 93 dealer staff accounts and their memberships.
-- Source: contract/dealers.json. Idempotent: every insert is guarded by its natural key.
-- Logos are original fictional emblems, 160x160 PNG data URLs (the dealer API accepts PNG/JPEG/WebP only).
SET NAMES utf8mb4;
SET time_zone = '+00:00';

